static int err_missing(const char *name)
{
    printf("cppcheck: error: argument to '%s' is missing.\n", name);
    return 1;
}

static int err_notinteger(const char *name)
{
    printf("cppcheck: error: argument to '%s' is not valid - not an integer.\n", name);
    return 1;
}

static int err_no_sources(void)
{
    printf("cppcheck: error: no C or C++ source files found.\n");
    return 1;
}

