{
    static char bad[128];
    const char *p = list;
    while (*p) {
        const char *q = strchr(p, ',');
        size_t n = q ? (size_t)(q - p) : strlen(p);
        if (n == 0 || n >= sizeof(bad)) {
            /* empty token -> treated as unknown */
            memcpy(bad, p, n);
            bad[n] = 0;
            return bad;
        }
        memcpy(bad, p, n);
        bad[n] = 0;
        if (!is_known_enable(bad)) return bad;
        if (!q) break;
        p = q + 1;
    }
    return NULL;
