        "c89", "c99", "c11", "c17", "c23",
        "c++03", "c++11", "c++14", "c++17", "c++20", "c++23", "c++26",
        NULL
    };
    for (int i = 0; known[i]; i++)
        if (strcmp(s, known[i]) == 0) return true;
    return false;
}

static bool is_known_language(const char *s)
