        if (a[0] != '-') {
            has_file = true;
            continue;
        }

        /* -D<def> */
        if (a[0] == '-' && a[1] == 'D') {
            if (a[2] == '\0') return err_missing("-D");
            continue;
        }
        /* -U<def> */
        if (a[0] == '-' && a[1] == 'U') {
            if (a[2] == '\0') return err_missing("-U");
            continue;
        }
        /* -I <dir> (arg with space) or -I<dir> */
        if (a[0] == '-' && a[1] == 'I') {
            if (a[2] == '\0') {
                if (i + 1 >= argc) return err_missing("-I");
                i++;
                continue;
            }
            continue;
        }
        /* -i <str> */
        if (a[0] == '-' && a[1] == 'i' && a[2] == '\0') {
            if (i + 1 >= argc) return err_missing("-i");
            i++;
            continue;
        }
        /* -j <jobs> or -j<jobs> */
        if (a[0] == '-' && a[1] == 'j') {
            const char *val;
            if (a[2] == '\0') {
                if (i + 1 >= argc) return err_missing("-j");
                val = argv[++i];
            } else {
                val = a + 2;
            }
            if (!is_uint_str(val)) return err_notinteger("-j");
            long v = strtol(val, NULL, 10);
            if (v <= 0) {
                printf("cppcheck: error: argument for '-j' must be greater than 0.\n");
                return 1;
            }
            continue;
        }
        /* -l <load> or -l<load> */
        if (a[0] == '-' && a[1] == 'l') {
            const char *val;
            if (a[2] == '\0') {
                if (i + 1 >= argc) return err_missing("-l");
                val = argv[++i];
            } else {
                val = a + 2;
            }
            if (!is_uint_str(val)) return err_notinteger("-l");
            continue;
        }
        /* -x <language> */
        if (a[0] == '-' && a[1] == 'x' && a[2] == '\0') {
            if (i + 1 >= argc) return err_missing("-x");
            const char *val = argv[++i];
            if (!is_known_language(val)) {
                printf("cppcheck: error: unknown language '%s' enforced.\n", val);
                return 1;
            }
            continue;
        }
        /* -E (preprocessor output) */
        if (strcmp(a, "-E") == 0) continue;
        /* -f / --force */
        if (strcmp(a, "-f") == 0 || strcmp(a, "--force") == 0) continue;
        /* -q / --quiet */
        if (strcmp(a, "-q") == 0 || strcmp(a, "--quiet") == 0) continue;
        /* -v / --verbose */
        if (strcmp(a, "-v") == 0 || strcmp(a, "--verbose") == 0) continue;

        /* Long options without argument */
        if (strcmp(a, "--check-config") == 0) continue;
        if (strcmp(a, "--check-library") == 0) continue;
        if (strcmp(a, "--dump") == 0) continue;
        if (strcmp(a, "--inconclusive") == 0) continue;
        if (strcmp(a, "--inline-suppr") == 0) continue;
        if (strcmp(a, "--xml") == 0) continue;
        if (strcmp(a, "--fsigned-char") == 0) continue;
        if (strcmp(a, "--funsigned-char") == 0) continue;
        if (strcmp(a, "--safety") == 0) continue;
        if (strcmp(a, "--report-progress") == 0) continue;
        if (strcmp(a, "--debug") == 0) continue;
        if (strcmp(a, "--debug-normal") == 0) continue;
        if (strcmp(a, "--debug-simplified") == 0) continue;
        if (strcmp(a, "--debug-warnings") == 0) continue;
        if (strcmp(a, "--exception-handling") == 0) continue;

        /* Long options with argument (--name=value) */
        if (startswith(a, "--enable=")) {
            const char *val = a + 9;
            if (*val == '\0') {
                printf("cppcheck: error: --enable parameter is empty\n");
                return 1;
            }
            const char *bad = first_bad_enable(val);
            if (bad) {
                printf("cppcheck: error: --enable parameter with the unknown name '%s'\n", bad);
                return 1;
            }
            continue;
        }
        if (startswith(a, "--disable=")) {
            const char *val = a + 10;
            if (*val == '\0') {
                printf("cppcheck: error: --disable parameter is empty\n");
                return 1;
            }
            const char *bad = first_bad_enable(val);
            if (bad) {
                printf("cppcheck: error: --disable parameter with the unknown name '%s'\n", bad);
                return 1;
            }
            continue;
        }
        if (startswith(a, "--std=")) {
            const char *val = a + 6;
            if (!is_known_std(val)) {
                printf("cppcheck: error: unknown --std value '%s'\n", val);
                return 1;
            }
            continue;
        }
        if (startswith(a, "--language=")) {
            const char *val = a + 11;
            if (!is_known_language(val)) {
                printf("cppcheck: error: unknown language '%s' enforced.\n", val);
                return 1;
            }
            continue;
        }
        if (startswith(a, "--platform=")) {
            const char *val = a + 11;
            if (*val == '\0') {
                printf("cppcheck: error: empty platform specified.\n");
                return 1;
            }
            /* Accept known platforms and also paths/filenames silently */
            (void)is_known_platform(val);
            continue;
        }
        if (startswith(a, "--library=")) {
            const char *val = a + 10;
            if (*val == '\0') {
                printf("cppcheck: error: empty library specified.\n");
                return 1;
            }
            continue;
        }
        if (startswith(a, "--error-exitcode=")) {
            const char *val = a + 17;
            if (!is_int_str(val)) return err_notinteger("--error-exitcode=");
            continue;
        }
        if (startswith(a, "--xml-version=")) {
            const char *val = a + 14;
            if (!is_int_str(val)) return err_notinteger("--xml-version=");
            long v = strtol(val, NULL, 10);
            if (v != 2 && v != 3) {
                printf("cppcheck: error: '--xml-version' can only be 2 or 3.\n");
                return 1;
            }
            continue;
        }
        if (startswith(a, "--max-configs=")) {
            const char *val = a + 14;
            if (!is_int_str(val)) return err_notinteger("--max-configs=");
            continue;
        }
        if (startswith(a, "--max-ctu-depth=")) {
            const char *val = a + 16;
            if (!is_int_str(val)) return err_notinteger("--max-ctu-depth=");
            continue;
        }
        if (startswith(a, "--suppress=")) {
            const char *val = a + 11;
            if (*val == '\0') {
                printf("cppcheck: error: Failed to add suppression. No id.\n");
                return 1;
            }
            /* Accept everything else */
            continue;
        }

        /* Generic accept-anything long options with '=' syntax */
        {
            static const char *accepted_eq[] = {
                "--addon=", "--addon-python=", "--cppcheck-build-dir=",
                "--check-level=", "--checkers-report=", "--clang=",
                "--config-exclude=", "--config-excludes-file=",
                "--exitcode-suppressions=", "--file-filter=", "--file-list=",
                "--includes-file=", "--include=", "--output-file=",
                "--output-format=", "--plist-output=", "--project=",
                "--project-configuration=", "--relative-paths=", "-rp=",
                "--report-type=", "--rule=", "--rule-file=", "--showtime=",
                "--suppressions-list=", "--suppress-xml=",
                "--template=", "--template-location=",
                NULL
            };
            bool matched = false;
            for (int k = 0; accepted_eq[k]; k++) {
                if (startswith(a, accepted_eq[k])) { matched = true; break; }
            }
            if (matched) continue;
        }

        return err_unrecognized(a);
    }

    if (!has_file) {
        return err_no_sources();
    }
    return err_std_cfg();
}
MAIN_EOF
echo done
